void AudioStreamPlaybackWAV::seek(double time) {
	if (base->format == AudioStreamWAV::FORMAT_IMA_ADPCM) {
		return; //no seeking in ima-adpcm
	}

	double max = base->get_length();
	if (time < 0) {
		time = 0;
	} else if (time >= max) {
		time = max - 0.001;
	}

	offset = int64_t(time * base->mix_rate);
}
